{"file_path":"/work/tests/test_spec.py","content":""""Regression checks for each section of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1
@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False], 0.0), ([True], 1.0),
     ([True, None, False, True], 0.5)],
)
def test_monitor_flag_rate_includes_none_in_denominator(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


# Section 2
@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("same", 1, True)],
        "large": [event("same", 1, True), event("b", 2, False), event("c", 3, None)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


# Section 3
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4
def test_parse_transcript_log_flag_values_and_field_whitespace():
    assert parse_transcript_log([" a , 2 , 1 \n", " b , -3 , 0 ", " c , 0 , \t"]) == [
        event("a", 2, True), event("b", -3, False), event("c", 0, None),
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", " \t# comment,not,a,record", "a,1,0", "\n"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, False)]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log([" ", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["a", "a,2", "a,2,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", " # skipped", "valid,1,1", bad_line])


# Section 5
def test_dedupe_transcripts_last_duplicate_id_wins_and_result_is_sorted():
    events = [
        event("b", 9, True),
        event("a", 2, True),
        event("c", 1, False),
        event("b", 2, None),
        event("a", 2, False),
    ]
    original = events.copy()
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]
    assert events == original
    assert dedupe_transcripts([]) == []


# Section 6
def test_daily_flag_counts_fills_gaps_and_respects_inclusive_range():
    events = [
        event("outside-before", 0, True), event("outside-after", 6, True),
        event("a", 1, True), event("b", 3, True), event("c", 3, True),
        event("d", 4, False), event("e", 4, None), event("f", 5, True),
    ]
    assert daily_flag_counts(events, 1, 5) == [1, 0, 2, 0, 1]
    assert daily_flag_counts(events, 3, 3) == [2]
    assert daily_flag_counts(events, 5, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (0, 0, [0]), (2, 1, [])])
def test_daily_flag_counts_without_events(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


def test_daily_flag_counts_negative_days():
    assert daily_flag_counts([event("a", -1, True)], -2, 0) == [0, 1, 0]


# Section 7
@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_without_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 0), (3, 1), (5, 2), (20, 2)])
def test_monitor_summary_pooled_rounding_calendar_days_and_nonempty_groups(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 3, True), event("c", 5, False), event("d", 5, None),
                  event("e", 1, False), event("f", 2, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


# Section 8
@pytest.mark.parametrize(
    "n, expected",
    [(0, []), (1, ["high"]), (3, ["high", "a", "z"]), (10, ["high", "a", "z", "low"])],
)
def test_top_flagged_groups_excludes_empty_and_sorts_ties_by_name(n, expected):
    groups = {
        "z": [event("z1", 1, True), event("z2", 1, None)],
        "empty": [],
        "low": [event("l", 1, False)],
        "a": [event("a1", 1, False), event("a2", 1, True)],
        "high": [event("h", 1, True)],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_without_transcripts(groups):
    assert top_flagged_groups(groups, 3) == []


# Section 9
def test_flag_rate_by_group_sorted_keys_and_empty_group_none():
    groups = {
        "z": [event("z", 1, None)],
        "b": [],
        "a": [event("a", 1, True), event("b", 1, False)],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.5, "b": None, "z": 0.0}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


# Section 10
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 2, 0, 1], 2), ([1, -1, 2], 1), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
